import re
from ..section_generic import TextBasedSectionGeneric
from ..utils.logger import logger
from auto_config.generator.utils.get_bts_config import Config


class SectionCtrl(TextBasedSectionGeneric):
    """
    Section "ctrl" is a part of cus.ini config file.
    Generated content base on ue.yaml, enb.yaml, eNB build release, hardware platform and TL type.
    Example generated for CLOUD_R4A_CUS:

    [ctrl_1]
    sectors   = 1,2,3,4,5,6
    ip_addr   = 192.168.200.1
    password  = root
    trsw_ip   = 10.0.2.2
    connector = EIF5
    """

    def __init__(self, subsection_separator='\n'):
        super().__init__(subsection_separator)
        self._section_header = '[ctrl_{}]'

    def _prepare_section_content(self, ue_config, enb_config, hw_config, execution_config, *args, **kwargs):
        cus_keys = self._get_cus_keys(ue_config)
        for i, cus_key in enumerate(cus_keys):
            cus_ent = ue_config[cus_key]
            cell_tab_per_cus = self.get_cell_tab_per_ctrl(cus_key, enb_config, hw_config)
            if not cell_tab_per_cus:
                logger.warning(f"Empty sector section declaration in ctrl_{str(i + 1)}. Skipping...")
                continue
            subsection_content = [
                self._section_header.format(str(i + 1)),
                f"sectors = {','.join(cell_tab_per_cus).strip(',')}",
                f"ip_addr = {cus_ent['ctrl_ip']}",
                f"trsw_ip = {cus_ent['trsw_ip']}"
            ]
            if not cell_tab_per_cus:
                subsection_content.append("disable_ctrl = true")

            if len(cus_keys) > 1:
                subsection_content.append(f'syslog_port = {51600 + i + 1}')

            if 'syslog_ip' in cus_ent:
                subsection_content.append(f'syslog_ip = {cus_ent["syslog_ip"]}')

            if not execution_config['is_fsm5']:
                subsection_content.append('connector = EIF5')

            sync_source = cus_ent.get('sync_source', '')
            if execution_config['release'] > 21.7 and sync_source not in ('', 'GPS'):
                subsection_content.append(f'sync_source = {cus_ent["sync_source"]}')
            self.add_et_type_params(subsection_content, execution_config)
            self._section_content.append(subsection_content)

    def get_cell_tab_per_ctrl(self, cus_key, enb_config, hw_config):
        ctrl_cus_id = re.search(r'cus(\d+)', cus_key).group(1)
        hw_map = self.get_hw_map(enb_config)
        radio_to_cus_map = self.get_radio_to_cus_map(hw_map, hw_config)
        sectors = self.get_enb_cell_id_tab_per_cus(radio_to_cus_map, enb_config, ctrl_cus_id)
        cell_id_to_cus_cell_id_map = self.get_cell_id_to_overall_cell_id_map(enb_config)

        sectors_tab_per_ctrl = []
        for enb_id, enb_cell_tab in sectors.items():
            for cell in enb_cell_tab:
                try:
                    sectors_tab_per_ctrl.append(str(cell_id_to_cus_cell_id_map[enb_id][cell]))
                except Exception:
                    pass
        return sorted(sectors_tab_per_ctrl, key=lambda x: int(x))

    @staticmethod
    def get_enb_cell_id_tab_per_cus(radio_to_cus_map, enb_config, ctrl_cus_id):
        enb_cell_id_tab_per_cus = {}
        for enb_key in radio_to_cus_map.keys():
            for radio, cus_id in radio_to_cus_map[enb_key].items():
                radio_id_from_map = radio.split('_')[1]
                for enb_cell_id in sorted(enb_config[enb_key]['cells'].keys(), key=int):
                    cell_params = enb_config[enb_key]['cells'][enb_cell_id]
                    _, enb_id = Config.unparse_bts_key(enb_key)
                    if radio_id_from_map == cell_params['channels'][0]['radio'] and cus_id == ctrl_cus_id:
                        if enb_id not in enb_cell_id_tab_per_cus:
                            enb_cell_id_tab_per_cus[enb_id] = [enb_cell_id]
                        else:
                            enb_cell_id_tab_per_cus[enb_id] = enb_cell_id_tab_per_cus[enb_id] + [enb_cell_id]
        return enb_cell_id_tab_per_cus

    @staticmethod
    def get_cell_id_to_overall_cell_id_map(enb_config):
        cell_id_to_cus_cell_id_map = {}
        overall_cell_id = 0
        for enb_key in enb_config.keys():
            _, enb_id = Config.unparse_bts_key(enb_key)
            for enb_cell_id in sorted(enb_config[enb_key]['cells'].keys(), key=int):
                overall_cell_id += 1
                if enb_id not in cell_id_to_cus_cell_id_map:
                    cell_id_to_cus_cell_id_map[enb_id] = {}
                cell_id_to_cus_cell_id_map[enb_id][enb_cell_id] = overall_cell_id
        return cell_id_to_cus_cell_id_map

    @staticmethod
    def get_radio_to_cus_map(hw_map, hw_config):
        radio_to_cus_map = {}
        for enb_key in hw_map.keys():
            enb_data = {}
            for bbmod, ports in hw_map[enb_key].items():
                for port, radio in ports.items():
                    enb_data[radio] = hw_config['rf_links'][enb_key][bbmod][port].split('.')[0]
            radio_to_cus_map[enb_key] = enb_data
        return radio_to_cus_map

    @staticmethod
    def get_hw_map(enb_config):
        hw_map = {}
        for enb, details in enb_config.items():
            bbmods_smods = {}
            for radio_id, radio_params in details['radios'].items():
                bbmod = radio_params.get('bbmod')
                smod = radio_params.get('smod')
                du = radio_params.get('du')
                port = radio_params['port']

                if bbmod:
                    if f"bbmod_{bbmod}" not in bbmods_smods:
                        bbmods_smods[f"bbmod_{bbmod}"] = {}
                    bbmods_smods[f"bbmod_{bbmod}"][f'port{port}'] = f'radio_{radio_id}'
                if smod:
                    if f"smod_{smod}" not in bbmods_smods:
                        bbmods_smods[f"smod_{smod}"] = {}
                    bbmods_smods[f"smod_{smod}"][f'port{port}'] = f'radio_{radio_id}'
                if du:
                    if f"du_{du}" not in bbmods_smods:
                        bbmods_smods[f"du_{du}"] = {}
                    bbmods_smods[f"du_{du}"][f'port{port}'] = f'radio_{radio_id}'

            hw_map[enb] = bbmods_smods
        return hw_map

    @staticmethod
    def add_et_type_params(subsection_content, execution_config):
        # if execution_config['configuration_type'] == 'ET':
        #     subsection_content.extend([
        #         'mirroring_l2_on_startup = 2',
        #         'mirroring_sch_on_startup = 2'
        #     ])
        pass

    @staticmethod
    def _get_cus_keys(ue_config):
        return sorted(key for key in ue_config if re.search(r'^cus\d+$', key))

    @staticmethod
    def _adjust_printing_style(subsection_content):
        printing_width = max([
            len(line.split('=')[0])
            if '=' in line else 0
            for line in subsection_content
        ])

        if printing_width == 10 or printing_width == 8:
            printing_width = 12

        subsection_content = [
            line.split('=')[0].ljust(printing_width) + '=' + line.split('=')[1]
            if '=' in line else line
            for line in subsection_content
        ]
        return subsection_content
